function validate([root1, root2]) {
  for (const tree of [root1, root2]) {
    if (!Array.isArray(tree) || tree.length === 0 || tree[0] === null) return 'Each tree needs at least one node.';
    let nodes = 0;
    let slots = 1;
    for (let i = 0; i < tree.length; i++) {
      if (i >= slots) return 'A tree lists children under a missing node.';
      if (tree[i] === null) continue;
      if (!Number.isInteger(tree[i]) || tree[i] < 0 || tree[i] > 200) return 'Node values are integers from 0 to 200.';
      nodes++;
      slots += 2;
    }
    if (nodes > 200) return 'Each tree has at most 200 nodes.';
  }
  return null;
}

