function leafSimilar(root1, root2) {
  // Iterative traversal with an explicit stack; push right before left so leaves come out left to right.
  const leafString = (root) => {
    const stack = [root];
    const out = [];
    while (stack.length) {
      const node = stack.pop();
      if (!node) continue;
      if (!node.left && !node.right) out.push(node.val);
      stack.push(node.right, node.left);
    }
    return out.join(',');
  };
  return leafString(root1) === leafString(root2);
}

