function generate(rand, size) {
  const large = size === 'large';
  const maxValue = large ? 200 : 4;
  const value = () => Math.floor(rand() * (maxValue + 1));
  let extra = 0;
  // Build a random tree whose leaves, left to right, are exactly the given values.
  const build = (leaves) => {
    if (extra < (large ? 15 : 2) && rand() < 0.15) {
      extra++;
      const node = { val: value(), left: null, right: null };
      if (rand() < 0.5) node.left = build(leaves);
      else node.right = build(leaves);
      return node;
    }
    if (leaves.length === 1) return { val: leaves[0], left: null, right: null };
    const cut = 1 + Math.floor(rand() * (leaves.length - 1));
    return { val: value(), left: build(leaves.slice(0, cut)), right: build(leaves.slice(cut)) };
  };
  const serialize = (root) => {
    const out = [];
    const queue = [root];
    for (let head = 0; head < queue.length; head++) {
      const node = queue[head];
      if (!node) { out.push(null); continue; }
      out.push(node.val);
      queue.push(node.left, node.right);
    }
    while (out[out.length - 1] === null) out.pop();
    return out;
  };
  const count = large ? 70 + Math.floor(rand() * 21) : 1 + Math.floor(rand() * 4);
  const leaves1 = Array.from({ length: count }, value);
  let leaves2 = leaves1.slice();
  const mode = rand();
  if (mode < 0.2) {
    leaves2 = Array.from({ length: large ? count : 1 + Math.floor(rand() * 4) }, value);
  } else if (mode < 0.45) {
    const at = Math.floor(rand() * count);
    const change = rand();
    if (change < 0.4) leaves2[at] = (leaves2[at] + 1) % (maxValue + 1);
    else if (change < 0.6 && count > 1) leaves2.splice(at, 1);
    else if (change < 0.8) leaves2.splice(at, 0, value());
    else if (count > 1) [leaves2[0], leaves2[count - 1]] = [leaves2[count - 1], leaves2[0]];
  }
  extra = 0;
  const root1 = serialize(build(leaves1));
  extra = 0;
  const root2 = serialize(build(leaves2));
  return [root1, root2];
}
